def surfaceArea(grid):
    n = len(grid)
    area = 0

    for i in range(n):
        for j in range(n):
            h = grid[i][j]
            if h > 0:
                # Add all sides and top/bottom by default
                area += 2 + 4 * h

                # Subtract faces hidden by cell below (i+1, j)
                if i + 1 < n:
                    area -= 2 * min(h, grid[i + 1][j])

                # Subtract faces hidden by cell to right (i, j+1)
                if j + 1 < n:
                    area -= 2 * min(h, grid[i][j + 1])
    return area
